// Написан вручную (две роли — генератор не умеет), не прогонялся — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/date-now.md 2.2 · кейс .qa/tests/date-now/DN-07.md
// Date Now включает только user2 (Premium). В finally: Date Now выкл., шаринг выкл., фильтры возвращены, сессии сохранены.
import { test, expect } from '../../fixtures';
import { enableSharing, disableSharing, openMap, userIdOf } from '../location-map/map-helpers';
import { saveSession } from '../_shared/session';
import { setupGeo, enableDateNow30, disableDateNow, pollNearby, findRow, widenAgePrefs, restoreAgePrefs, DN_GEO, type AgePrefs } from './date-now-helpers';

test.describe('דייט עכשיו — что видят другие', () => {
  test.describe.configure({ timeout: 300_000 });
  test('При активном Date Now подбор по текущему местоположению: ТА → Иерусалим → ТА @iphone @data (#1fd43a)', async ({ asUser }) => {
    const user2 = await asUser('user2');
    const reg1 = await asUser('reg1');
    await setupGeo(user2, 'user2');
    await setupGeo(reg1, 'reg1');
    const reg1Id = userIdOf('reg1');
    let prefsReg1: AgePrefs | undefined;
    let prefsUser2: AgePrefs | undefined;
    try {
      // 1. Предусловия: фильтры шире, шаринг у обоих, Date Now у user2
      prefsReg1 = await widenAgePrefs(reg1);
      prefsUser2 = await widenAgePrefs(user2);
      await enableSharing(reg1);
      await enableSharing(user2);
      await openMap(user2);
      await enableDateNow30(user2);

      // 2. ТА: reg1 рядом (AC 4)
      await pollNearby(user2, (rows) => findRow(rows, reg1Id).idx >= 0, 'ТА: reg1 в nearby_live user2');

      // 3. Иерусалим: reg1 пропадает, «אין כרגע אנשים בקרבתך»
      await user2.context().setGeolocation({ ...DN_GEO.jerusalem, accuracy: 10 });
      await pollNearby(user2, (rows) => findRow(rows, reg1Id).idx < 0, 'Иерусалим: reg1 нет в nearby_live user2');
      await expect(user2.getByText('אין כרגע אנשים בקרבתך')).toBeVisible();

      // 4. Обратно в ТА: reg1 снова есть
      await user2.context().setGeolocation({ ...DN_GEO.user2, accuracy: 10 });
      await pollNearby(user2, (rows) => findRow(rows, reg1Id).idx >= 0, 'снова ТА: reg1 в nearby_live user2');
    } finally {
      await user2.context().setGeolocation({ ...DN_GEO.user2, accuracy: 10 }).catch(() => {});
      await disableDateNow(user2).catch(() => {});
      for (const p of [user2, reg1]) await disableSharing(p).catch(() => {});
      await restoreAgePrefs(prefsReg1).catch(() => {});
      await restoreAgePrefs(prefsUser2).catch(() => {});
      await saveSession(user2, 'user2');
      await saveSession(reg1, 'reg1');
    }
  });
});
